class Solution:
    def multiply(self, num1: str, num2: str) -> str:
        def add(a: str, b: str) -> str:
            i, j, carry, out = len(a) - 1, len(b) - 1, 0, []
            while i >= 0 or j >= 0 or carry:
                total = carry
                if i >= 0:
                    total += ord(a[i]) - ord('0')
                    i -= 1
                if j >= 0:
                    total += ord(b[j]) - ord('0')
                    j -= 1
                out.append(str(total % 10))
                carry = total // 10
            return ''.join(reversed(out))

        def dec(s: str) -> str:
            digits = list(s)
            i = len(digits) - 1
            while digits[i] == '0':
                digits[i] = '9'
                i -= 1
            digits[i] = str(ord(digits[i]) - ord('0') - 1)
            return ''.join(digits).lstrip('0') or "0"

        if num1 == "0" or num2 == "0":
            return "0"
        result = "0"
        times = num2
        while times != "0":
            result = add(result, num1)
            times = dec(times)
        return result

